<script setup lang="ts">
import{computed,ref,watch}from'vue';import{useRoute,useRouter}from'vue-router';import{ChevronRight,Share2,Info,ShieldCheck,WifiOff,AlertCircle,ArrowUpRight}from'lucide-vue-next';import{states,cities,locationsError}from'../composables/useLocations';import{useElection}from'../composables/useElection';import{offices,type Office}from'../types/election';import{dateTime}from'../utils/format';import LocationPicker from'../components/location/LocationPicker.vue';import ProgressPanel from'../components/election/ProgressPanel.vue';import CandidateList from'../components/candidates/CandidateList.vue';import StatisticsGrid from'../components/statistics/StatisticsGrid.vue';import BrazilMap from'../components/map/BrazilMap.vue';import CitiesList from'../components/cities/CitiesList.vue';import ProgressHistory from'../components/charts/ProgressHistory.vue';
const route=useRoute(),router=useRouter();const uf=computed(()=>String(route.params.uf||'br').toLowerCase()),city=computed(()=>route.params.city?String(route.params.city):null);const office=computed<Office>(()=>{const o=String(route.query.cargo||'1')as Office;return uf.value==='br'?'1':offices.some(x=>x.id===o)?o:'1'});const state=computed(()=>states.value.find(s=>s.uf===uf.value));const municipality=computed(()=>cities.value.find(c=>c.uf===uf.value&&c.slug===city.value));const location=computed(()=>municipality.value?.name||state.value?.name||(uf.value==='br'?'Brasil':uf.value.toUpperCase()));const officeName=computed(()=>offices.find(o=>o.id===office.value)?.name);const availableOffices=computed(()=>offices.filter(o=>uf.value==='br'?o.id==='1':uf.value==='df'?o.id!=='7':o.id!=='8'));const{data,loading,updating,error,offline,stale,history,refresh}=useElection(uf,city,office);const shareText=ref('Compartilhar');async function share(){try{if(navigator.share)await navigator.share({title:`Apura • ${location.value} • ${officeName.value}`,url:window.location.href});else{await navigator.clipboard.writeText(window.location.href);shareText.value='Link copiado';setTimeout(()=>shareText.value='Compartilhar',2500)}}catch{shareText.value='Copie a URL do navegador'}}function selectOffice(o:Office){if(uf.value==='br'&&o!=='1')router.push({path:'/estado/pr',query:{cargo:o}});else router.replace({query:{...route.query,cargo:o}})}watch([location,officeName],()=>document.title=`${officeName.value} em ${location.value} • Eleições 2026 | Apura`,{immediate:true});
</script>
<template><main class="container results-main"><div class="breadcrumb"><RouterLink to="/brasil">Brasil</RouterLink><template v-if="uf!=='br'"><ChevronRight :size="13"/><RouterLink :to="'/estado/'+uf">{{state?.name||uf.toUpperCase()}}</RouterLink></template><template v-if="city"><ChevronRight :size="13"/><span>{{municipality?.name||city}}</span></template></div><div class="page-title-row"><div><div class="eyebrow">ELEIÇÕES 2026 <span>1º TURNO</span></div><h1>{{city?`${location} — ${uf.toUpperCase()}`:uf==='br'?'O Brasil, voto a voto.':`Apuração · ${state?.name||location}`}}</h1><p class="page-subtitle">{{city?`Acompanhe a apuração em ${location}.`:uf==='br'?'Acompanhe os resultados em todo o país.':'Resultados oficiais por cargo e município.'}}</p></div><LocationPicker :uf="uf" :city="city"/></div><div class="office-tabs" role="tablist" aria-label="Cargo eleitoral"><button v-for="o in availableOffices" :key="o.id" role="tab" :aria-selected="office===o.id" :class="{active:office===o.id}" @click="selectOffice(o.id)">{{o.short}}</button><span class="tabs-note" v-if="uf==='br'">Cargos estaduais: selecione uma UF</span></div><div class="result-title"><div><h2>{{officeName}}<span class="title-location">{{uf==='br'?'Brasil':location}}</span></h2><span class="live-badge" :class="{waiting:!data||stale}"><span class="tiny-dot"></span>{{data?.finished?'TOTALIZAÇÃO FINAL':!data?'CONSULTANDO':stale?'ÚLTIMA LEITURA':'EM APURAÇÃO'}}</span></div><button class="share-button" @click="share"><Share2 :size="15"/><span>{{shareText}}</span></button></div><div v-if="offline||error||stale" class="connection-banner" role="status"><WifiOff v-if="offline" :size="18"/><AlertCircle v-else :size="18"/><span>{{offline?'Sem conexão com a internet. ':''}}{{error?(data?'Não foi possível obter uma nova atualização. Exibindo os últimos dados disponíveis.':error):stale?'A fonte ainda não forneceu uma leitura recente. Confira o horário da última atualização.':''}}</span><button @click="refresh">Tentar novamente</button></div><ProgressPanel :data="data" :updating="updating" :stale="stale" @refresh="refresh"/><div v-if="data&&!data.disclosed" class="inline-message"><Info :size="16"/> A divulgação dos votos ainda não está liberada pelo TSE nesta localização.</div><div class="main-results-grid"><CandidateList :key="uf+city+office" :candidates="data?.candidates||[]" :loading="loading" :office="office"/><div class="right-column"><BrazilMap/><div class="source-note"><ShieldCheck :size="19"/><div><strong>Direto da fonte, com transparência.</strong><p>Dados oficiais do TSE. Os resultados são parciais até a conclusão da totalização.</p></div></div></div></div><StatisticsGrid :stats="data?.stats||null"/><CitiesList v-if="uf!=='br'" :uf="uf" :office="office"/><div class="bottom-grid"><ProgressHistory :history="history"/><aside class="about-count panel"><div class="about-icon"><Info :size="21"/></div><h2>Entenda os resultados</h2><p>Os votos são atualizados à medida que os boletins de urna são recebidos e processados pela Justiça Eleitoral.</p><p>A liderança parcial não indica eleição. A situação de cada candidatura é informada pelo TSE.</p><a href="https://resultados.tse.jus.br/oficial/app/index.html" target="_blank" rel="noopener noreferrer">Acessar a fonte oficial <ArrowUpRight :size="16"/></a></aside></div><div class="last-updated"><ShieldCheck :size="14"/><span>Última atualização: {{dateTime(data?.updatedAt)}} <template v-if="data">(horário de Brasília)</template></span><a v-if="data" :href="data.source" target="_blank" rel="noopener noreferrer">Ver arquivo de origem</a></div><p v-if="locationsError" class="small muted">{{locationsError}}</p></main></template>
